+fn cv_b(a:Body,b:Body,key:u32) {
+    if(cv_on!=0u) { for(var i=0u;i<3u;i++) {
+        atomicMax(&cv_velocity,bitcast<u32>(cv_change(a.vel[i],b.vel[i])));
+        atomicMax(&cv_velocity,bitcast<u32>(cv_change(a.omega[i],b.omega[i])));
+        let value=max(cv_change(a.vel[i],b.vel[i]),cv_change(a.omega[i],b.omega[i]));
